package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsGrand decimal.Decimal = decimal.NewFromInt(0)
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var orderRec OrderRec
var inputLines []string
var inputIndex int

func main() {
	f, err := os.Open("input.dat")
	if err == nil {
		sc := bufio.NewScanner(f)
		// Allow long lines; increase buffer
		buf := make([]byte, 0, 64*1024)
		sc.Buffer(buf, 10*1024*1024)
		for sc.Scan() {
			line := sc.Text()
			inputLines = append(inputLines, line)
		}
		f.Close()
	} else {
		if !os.IsNotExist(err) {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	MAIN_PARA()
}

func fitToPic(v decimal.Decimal, intDigits int, decDigits int) decimal.Decimal {
	modPow := intDigits + decDigits
	modulus := decimal.New(1, int32(modPow))
	scaled := v.Shift(int32(decDigits)).Truncate(0)
	// keep low order digits: scaled mod modulus (positive values)
	if scaled.IsNegative() {
		// not needed for this program, but handle
		neg := scaled.Abs().Mod(modulus)
		if neg.IsZero() {
			scaled = decimal.Zero
		} else {
			scaled = modulus.Sub(neg)
		}
	} else {
		scaled = scaled.Mod(modulus)
	}
	return scaled.Shift(int32(-decDigits))
}

func formatEdited(v decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	decDigits := 0
	for _, c := range fracPic {
		if c == '9' || c == 'Z' {
			decDigits++
		}
	}
	intPlaceCount := 0
	for _, c := range intPic {
		if c == '9' || c == 'Z' {
			intPlaceCount++
		}
	}
	// split value into integer and fractional absolute
	absVal := v.Abs()
	scaled := absVal.Shift(int32(decDigits)).Truncate(0)
	// integer part and frac part via division
	pow10 := decimal.New(1, int32(decDigits))
	intPart := decimal.Zero
	fracPart := decimal.Zero
	if decDigits > 0 {
		intPart = scaled.Div(pow10).Truncate(0)
		fracPart = scaled.Mod(pow10)
	} else {
		intPart = scaled
	}
	intStrRaw := intPart.StringFixed(0) // without exponent
	// intPart 0 => "0"
	if intStrRaw == "" {
		intStrRaw = "0"
	}
	// high-order truncation
	if len(intStrRaw) > intPlaceCount {
		intStrRaw = intStrRaw[len(intStrRaw)-intPlaceCount:]
	}
	// left pad with zeros to place count
	if len(intStrRaw) < intPlaceCount {
		intStrRaw = strings.Repeat("0", intPlaceCount-len(intStrRaw)) + intStrRaw
	}
	fracStrRaw := ""
	if decDigits > 0 {
		fracStrRaw = fracPart.StringFixed(0)
		if len(fracStrRaw) < decDigits {
			fracStrRaw = strings.Repeat("0", decDigits-len(fracStrRaw)) + fracStrRaw
		}
		if len(fracStrRaw) > decDigits {
			fracStrRaw = fracStrRaw[len(fracStrRaw)-decDigits:]
		}
	}

	// Build result array from picture
	res := []rune(picture)
	// Fill integer digit placeholders left to right
	intDigitIdx := 0
	for i, ch := range intPic {
		if ch == '9' || ch == 'Z' {
			res[i] = rune(intStrRaw[intDigitIdx])
			intDigitIdx++
		} else {
			// comma stays for now
		}
	}
	// Fill fractional part
	if dotIdx >= 0 {
		fracDigitIdx := 0
		for i := 0; i < len(fracPic); i++ {
			picCh := fracPic[i]
			resIdx := dotIdx + 1 + i
			if picCh == '9' || picCh == 'Z' {
				res[resIdx] = rune(fracStrRaw[fracDigitIdx])
				fracDigitIdx++
			} else {
				// literal
			}
		}
	}
	// Apply Z suppression for integer part (up to dot)
	suppressed := true
	for i := 0; i < len(intPic); i++ {
		pc := intPic[i]
		switch pc {
		case 'Z':
			if suppressed && res[i] == '0' {
				res[i] = ' '
			} else {
				suppressed = false
			}
		case '9':
			suppressed = false
		case ',':
			if suppressed {
				res[i] = ' '
			} else {
				res[i] = ','
			}
		}
	}
	return string(res)
}

func format99(n int64) string {
	m := n % 100
	if m < 0 {
		m += 100
	}
	return fmt.Sprintf("%02d", m)
}

func MAIN_PARA() {
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	SUMMARY_PARA()
}

func READ_PARA() {
	if inputIndex >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIndex]
	inputIndex++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	orId := line[0:5]
	orStat := line[5:6]
	orQtyStr := line[6:9]
	orPriceStr := line[9:15]

	var qty int64
	trimmed := strings.TrimSpace(orQtyStr)
	if trimmed == "" {
		qty = 0
	} else {
		var v int64
		fmt.Sscanf(trimmed, "%d", &v)
		qty = v
		// ensure low-order digits if overflow? PIC 9(3) overflow keep low 3 digits
		// but parsing already limited to 3 chars
	}
	var price decimal.Decimal
	priceTrim := strings.TrimSpace(orPriceStr)
	if priceTrim == "" {
		price = decimal.Zero
	} else {
		// digits only; implied V99
		var iv int64
		fmt.Sscanf(priceTrim, "%d", &iv)
		price = decimal.New(iv, -2)
	}

	orderRec = OrderRec{
		OrId:    orId,
		OrStat:  orStat,
		OrQty:   qty,
		OrPrice: price,
	}
}

func PROCESS_PARA() {
	WsTotal = decimal.Zero
	// EVALUATE TRUE
	if orderRec.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Printf("%s BAD QTY\n", orderRec.OrId)
	} else if orderRec.OrStat == "N" {
		prod := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice)
		prod = prod.Truncate(2)
		WsTotal = fitToPic(prod, 8, 2)
		WsNewCount = (WsNewCount + 1) % 100
		SHOW_PARA()
	} else if orderRec.OrStat == "S" {
		prod := decimal.NewFromInt(orderRec.OrQty).Mul(orderRec.OrPrice).Mul(decimal.New(105, -2))
		prod = prod.Round(2)
		WsTotal = fitToPic(prod, 8, 2)
		WsShipCount = (WsShipCount + 1) % 100
		SHOW_PARA()
	} else if orderRec.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		SHOW_PARA()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Printf("%s BAD STATUS %s\n", orderRec.OrId, orderRec.OrStat)
	}
	WsGrand = WsGrand.Add(WsTotal)
	WsGrand = fitToPic(WsGrand, 10, 2)
	READ_PARA()
}

func SHOW_PARA() {
	WsQtyEd = formatEdited(decimal.NewFromInt(orderRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(orderRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", orderRec.OrId, orderRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SUMMARY_PARA() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("NEW: %s SHIPPED: %s CANCELLED: %s\n", format99(WsNewCount), format99(WsShipCount), format99(WsCancelCount))
	fmt.Printf("INVALID: %s BAD QTY: %s\n", format99(WsInvalid), format99(WsBadQty))
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}
